fn solve(r: i8, g: i8, b: i8) -> i8 {
    // We compute four candidate values:
    // 1) floor((r + g + b) / 3)
    // 2) r + g
    // 3) r + b
    // 4) g + b
    //
    // The answer is the minimum of those four.
    //
    // We cast to i32 to avoid overflow when summing up to 127 + 127 = 254.
    let r = r as i32;
    let g = g as i32;
    let b = b as i32;

    let total = r + g + b;
    let by_three = total / 3;
    let sum_rg = r + g;
    let sum_rb = r + b;
    let sum_gb = g + b;

    let ans = by_three
        .min(sum_rg)
        .min(sum_rb)
        .min(sum_gb);

    // The result by construction fits into i8 (max total/3 ≤ 127).
    ans as i8
}